_choice_cmake_cache_entry() {
    local file="${argc_B:-.}/CMakeCache.txt"
    [[ -f "$file" ]] || return 0
    sed -n 's/^\([A-Za-z_][A-Za-z0-9_.-]*\):[A-Za-z][A-Za-z0-9_]*=.*/\1/p' "$file"
}

_choice_cmake_generator() {
    cmake --help 2>/dev/null | gawk '
        /^Generators$/ { in_generators = 1; next }
        in_generators && /^[[:space:]]*$/ && found { exit }
        in_generators && /=/ {
            line = $0
            sub(/^[*[:space:]]+/, "", line)
            sub(/[[:space:]]*=.*/, "", line)
            print line
            found = 1
        }'
}

_choice_cmake_help() {
    _choice_cmake_help_manual
    _choice_cmake_help_command
    _choice_cmake_help_diagnostic
    _choice_cmake_help_module
    _choice_cmake_help_policy
    _choice_cmake_help_property
    _choice_cmake_help_variable
}

