_choice_cmake_preset() {
    local dir file
    if [[ -n ${argc_presets_file:-} ]]; then
        jq -b -r '.configurePresets[]? | .name' "$argc_presets_file" 2>/dev/null
        return 0
    fi
    dir="${argc_S:-}"
    if [[ -z "$dir" ]]; then
        dir="$(_argc_util_path_search_parent -p CMakePresets.json)"
    fi
    [[ -n "$dir" ]] || dir="."
    for file in "$dir/CMakePresets.json" "$dir/CMakeUserPresets.json"; do
        [[ -f "$file" ]] || continue
        jq -b -r '.configurePresets[]? | .name' "$file" 2>/dev/null
    done
}
